/* ============================================
   GlobalStone — Global Commercial Real Estate
   Design System & Global Styles
   ============================================ */

/* CSS Variables */
:root {
  --primary-dark: #0A1628;
  --primary-green: #003F2D;
  --secondary-teal: #012A2D;
  --accent-gold: #C9A227;
  --accent-teal: #0D7377;
  --neutral-100: #F5F5F5;
  --neutral-200: #E6E6E6;
  --neutral-300: #CCCCCC;
  --neutral-400: #999999;
  --neutral-500: #666666;
  --neutral-600: #444444;
  --neutral-700: #222222;
  --white: #FFFFFF;
  --black: #000000;

  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-heading: 'Playfair Display', Georgia, 'Times New Roman', serif;

  --transition-fast: 0.15s ease;
  --transition-base: 0.25s ease;
  --transition-slow: 0.4s ease;

  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 12px 40px rgba(0,0,0,0.12);
  --shadow-xl: 0 24px 60px rgba(0,0,0,0.16);

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;

  --container-max: 1280px;
  --container-padding: 24px;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--neutral-600);
  background-color: var(--white);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
  transition: color var(--transition-fast);
}

ul, ol {
  list-style: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-heading);
  color: var(--primary-dark);
  line-height: 1.2;
  font-weight: 600;
}

h1 { font-size: clamp(2.5rem, 5vw, 4rem); }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }

p {
  margin-bottom: 1rem;
}

/* Utility Classes */
.container {
  max-width: var(--container-max);
  margin: 0 auto;
  padding: 0 var(--container-padding);
}

.section-padding {
  padding: 80px 0;
}

.section-padding-sm {
  padding: 48px 0;
}

.text-center {
  text-align: center;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.025em;
  text-transform: uppercase;
  border-radius: var(--radius-sm);
  transition: all var(--transition-base);
  cursor: pointer;
}

.btn-primary {
  background-color: var(--accent-gold);
  color: var(--primary-dark);
}

.btn-primary:hover {
  background-color: #B8941F;
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background-color: transparent;
  color: var(--white);
  border: 1px solid rgba(255,255,255,0.4);
}

.btn-secondary:hover {
  background-color: rgba(255,255,255,0.1);
  border-color: var(--white);
}

.btn-dark {
  background-color: var(--primary-dark);
  color: var(--white);
}

.btn-dark:hover {
  background-color: var(--secondary-teal);
}

.btn-outline-dark {
  background-color: transparent;
  color: var(--primary-dark);
  border: 1px solid var(--primary-dark);
}

.btn-outline-dark:hover {
  background-color: var(--primary-dark);
  color: var(--white);
}

/* Link with arrow */
.link-arrow {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.025em;
  color: var(--accent-gold);
  transition: gap var(--transition-fast);
}

.link-arrow:hover {
  gap: 10px;
}

.link-arrow svg {
  width: 16px;
  height: 16px;
}

/* Overline */
.overline {
  display: block;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.15em;
  color: var(--accent-gold);
  margin-bottom: 12px;
}

/* ============================================
   HEADER & NAVIGATION
   ============================================ */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background-color: var(--white);
  border-bottom: 1px solid var(--neutral-200);
  transition: box-shadow var(--transition-base);
}

.header.scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
}

.logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary-dark);
  letter-spacing: -0.02em;
}

.logo span {
  color: var(--accent-gold);
}

/* Desktop Nav */
.nav-desktop {
  display: none;
}

.nav-desktop ul {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-desktop a {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--neutral-600);
  transition: color var(--transition-fast);
}

.nav-desktop a:hover {
  color: var(--primary-dark);
}

.nav-item-has-mega {
  position: relative;
}

.nav-item-has-mega > a {
  display: flex;
  align-items: center;
  gap: 4px;
}

.nav-item-has-mega svg {
  width: 14px;
  height: 14px;
  transition: transform var(--transition-fast);
}

.nav-item-has-mega.active svg {
  transform: rotate(180deg);
}

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: calc(100% + 1px);
  left: 50%;
  transform: translateX(-50%) translateY(-8px);
  width: 720px;
  background-color: var(--white);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-xl);
  padding: 32px;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: all var(--transition-base);
}

.nav-item-has-mega.active .mega-menu {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateX(-50%) translateY(0);
}

.mega-menu-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
}

.mega-menu h4 {
  font-family: var(--font-body);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--neutral-400);
  margin-bottom: 16px;
}

.mega-menu ul {
  display: flex;
  flex-direction: column;
  gap: 0;
}

.mega-menu li {
  border-bottom: 1px solid var(--neutral-200);
}

.mega-menu li:last-child {
  border-bottom: none;
}

.mega-menu a {
  display: block;
  padding: 12px 0;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--neutral-700);
  transition: color var(--transition-fast), padding-left var(--transition-fast);
}

.mega-menu a:hover {
  color: var(--accent-gold);
  padding-left: 4px;
}

/* Mobile Nav Toggle */
.nav-toggle {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  z-index: 1001;
}

.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background-color: var(--primary-dark);
  transition: all var(--transition-base);
}

.nav-toggle.active span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.nav-toggle.active span:nth-child(2) {
  opacity: 0;
}

.nav-toggle.active span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile Nav Panel */
.nav-mobile {
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  bottom: 0;
  background-color: var(--white);
  z-index: 999;
  padding: 24px;
  overflow-y: auto;
  transform: translateX(100%);
  transition: transform var(--transition-base);
}

.nav-mobile.active {
  transform: translateX(0);
}

.nav-mobile ul {
  display: flex;
  flex-direction: column;
}

.nav-mobile li {
  border-bottom: 1px solid var(--neutral-200);
}

.nav-mobile a {
  display: block;
  padding: 16px 0;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--neutral-700);
}

.mobile-accordion-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 16px 0;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--neutral-700);
  background: none;
  border: none;
  cursor: pointer;
}

.mobile-accordion-toggle svg {
  width: 18px;
  height: 18px;
  transition: transform var(--transition-fast);
}

.mobile-accordion-toggle.active svg {
  transform: rotate(180deg);
}

.mobile-submenu {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base);
}

.mobile-submenu.open {
  max-height: 600px;
}

.mobile-submenu li {
  border-bottom: none;
}

.mobile-submenu a {
  padding: 10px 0 10px 16px;
  font-size: 0.9375rem;
  color: var(--neutral-500);
}

.mobile-submenu a:hover {
  color: var(--accent-gold);
}

/* ============================================
   HERO SECTION
   ============================================ */
.hero {
  position: relative;
  min-height: 80vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background-color: var(--primary-dark);
}

.hero-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  opacity: 0.5;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(10, 22, 40, 0.6) 0%,
    rgba(10, 22, 40, 0.8) 100%
  );
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  padding: 120px var(--container-padding) 80px;
  text-align: center;
}

.hero h1 {
  color: var(--white);
  margin-bottom: 20px;
}

.hero p {
  color: rgba(255,255,255,0.85);
  font-size: 1.125rem;
  margin-bottom: 32px;
}

.hero-actions {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* Hero compact variant */
.hero-compact {
  min-height: 50vh;
}

.hero-compact .hero-content {
  padding: 100px var(--container-padding) 60px;
}

/* ============================================
   FEATURED INSIGHTS
   ============================================ */
.featured-insights {
  background-color: var(--neutral-100);
}

.featured-insights-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
}

.insight-card {
  background-color: var(--white);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition-base), transform var(--transition-base);
}

.insight-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.insight-card-image {
  height: 180px;
  background-size: cover;
  background-position: center;
  position: relative;
}

.insight-card-image::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 40%, rgba(10,22,40,0.7) 100%);
}

.insight-card-tag {
  position: absolute;
  bottom: 12px;
  left: 16px;
  z-index: 2;
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--accent-gold);
  background-color: rgba(10,22,40,0.8);
  padding: 4px 10px;
  border-radius: var(--radius-sm);
}

.insight-card-content {
  padding: 20px;
}

.insight-card-content h3 {
  font-family: var(--font-body);
  font-size: 1rem;
  font-weight: 600;
  color: var(--neutral-700);
  line-height: 1.4;
  margin-bottom: 12px;
}

/* ============================================
   ANNOUNCEMENT BANNER
   ============================================ */
.announcement-banner {
  background-color: var(--primary-green);
  color: var(--white);
  padding: 16px 0;
}

.announcement-banner-inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  flex-wrap: wrap;
  text-align: center;
}

.announcement-banner p {
  font-size: 0.9375rem;
  font-weight: 500;
  margin: 0;
}

.announcement-banner .link-arrow {
  color: var(--accent-gold);
  font-size: 0.8125rem;
}

/* ============================================
   ABOUT STATEMENT
   ============================================ */
.about-statement {
  background-color: var(--white);
}

.about-statement-inner {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.about-statement h2 {
  margin-bottom: 20px;
}

.about-statement p {
  font-size: 1.125rem;
  color: var(--neutral-500);
  margin-bottom: 28px;
}

/* ============================================
   WHAT WE DO (TABBED SECTION)
   ============================================ */
.what-we-do {
  background-color: var(--neutral-100);
}

.what-we-do-header {
  text-align: center;
  margin-bottom: 48px;
}

.tabs-wrapper {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 40px;
  max-width: 1000px;
  margin: 0 auto;
}

.tabs-nav {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.tab-btn {
  text-align: left;
  padding: 18px 24px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--neutral-500);
  background-color: transparent;
  border-left: 3px solid transparent;
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  transition: all var(--transition-base);
}

.tab-btn:hover {
  color: var(--neutral-700);
  background-color: rgba(255,255,255,0.5);
}

.tab-btn.active {
  color: var(--primary-dark);
  background-color: var(--white);
  border-left-color: var(--accent-gold);
  box-shadow: var(--shadow-sm);
}

.tabs-panels {
  position: relative;
}

.tab-panel {
  display: none;
  animation: fadeIn 0.3s ease;
}

.tab-panel.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.tab-panel h3 {
  margin-bottom: 16px;
}

.tab-panel p {
  color: var(--neutral-500);
  margin-bottom: 24px;
}

/* ============================================
   NEWSLETTER
   ============================================ */
.newsletter {
  background-color: var(--primary-dark);
  color: var(--white);
}

.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.newsletter-content h2 {
  color: var(--white);
  margin-bottom: 12px;
}

.newsletter-content p {
  color: rgba(255,255,255,0.75);
  margin-bottom: 0;
}

.newsletter-form {
  display: flex;
  gap: 12px;
}

.newsletter-form input {
  flex: 1;
  padding: 14px 18px;
  font-size: 0.9375rem;
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: var(--radius-sm);
  background-color: rgba(255,255,255,0.05);
  color: var(--white);
  outline: none;
  transition: border-color var(--transition-fast);
}

.newsletter-form input::placeholder {
  color: rgba(255,255,255,0.4);
}

.newsletter-form input:focus {
  border-color: var(--accent-gold);
}

/* ============================================
   LATEST INSIGHTS
   ============================================ */
.latest-insights {
  background-color: var(--white);
}

.latest-insights-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 40px;
}

.latest-insights-header h2 {
  margin-bottom: 0;
}

.insights-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 24px;
}

.insight-item {
  display: grid;
  grid-template-columns: 120px 1fr;
  gap: 16px;
  padding: 16px;
  border-radius: var(--radius-md);
  background-color: var(--neutral-100);
  transition: box-shadow var(--transition-base);
}

.insight-item:hover {
  box-shadow: var(--shadow-md);
}

.insight-item-image {
  width: 120px;
  height: 100px;
  background-size: cover;
  background-position: center;
  border-radius: var(--radius-sm);
}

.insight-item-meta {
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.insight-item-meta .tag {
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--accent-gold);
  margin-bottom: 6px;
}

.insight-item-meta h4 {
  font-family: var(--font-body);
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--neutral-700);
  line-height: 1.4;
  margin-bottom: 6px;
}

.insight-item-meta .date {
  font-size: 0.8125rem;
  color: var(--neutral-400);
}

/* ============================================
   OUR COMMITMENT
   ============================================ */
.our-commitment {
  background-color: var(--neutral-100);
}

.commitment-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 24px;
}

.commitment-card {
  background-color: var(--white);
  padding: 32px;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition-base), transform var(--transition-base);
}

.commitment-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.commitment-card h3 {
  margin-bottom: 12px;
}

.commitment-card p {
  font-size: 0.9375rem;
  color: var(--neutral-500);
  margin-bottom: 20px;
}

/* ============================================
   SERVICE CATEGORIES GRID
   ============================================ */
.service-categories {
  background-color: var(--white);
}

.services-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(340px, 1fr));
  gap: 24px;
}

.service-card {
  background-color: var(--neutral-100);
  padding: 36px;
  border-radius: var(--radius-md);
  border-top: 3px solid transparent;
  transition: all var(--transition-base);
}

.service-card:hover {
  background-color: var(--white);
  border-top-color: var(--accent-gold);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.service-card h3 {
  margin-bottom: 12px;
}

.service-card p {
  font-size: 0.9375rem;
  color: var(--neutral-500);
  margin-bottom: 20px;
}

/* ============================================
   CAPABILITIES GRID
   ============================================ */
.capabilities {
  background-color: var(--neutral-100);
}

.capabilities-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 24px;
}

.capability-card {
  background-color: var(--white);
  padding: 32px;
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition-base);
}

.capability-card:hover {
  box-shadow: var(--shadow-md);
}

.capability-card h3 {
  margin-bottom: 10px;
}

.capability-card p {
  font-size: 0.9375rem;
  color: var(--neutral-500);
  margin-bottom: 16px;
}

/* ============================================
   PARTNERSHIP HIGHLIGHT
   ============================================ */
.partnership-highlight {
  background-color: var(--primary-dark);
  color: var(--white);
}

.partnership-highlight-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.partnership-highlight h2 {
  color: var(--white);
  margin-bottom: 20px;
}

.partnership-highlight p {
  color: rgba(255,255,255,0.8);
  margin-bottom: 16px;
}

.partnership-stats {
  display: flex;
  gap: 40px;
  margin-top: 32px;
}

.stat-item h4 {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  color: var(--accent-gold);
  margin-bottom: 4px;
}

.stat-item p {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.6);
  margin: 0;
}

/* ============================================
   FEATURED TOPICS
   ============================================ */
.featured-topics {
  background-color: var(--white);
}

.topics-list {
  display: flex;
  flex-direction: column;
  gap: 0;
  max-width: 500px;
}

.topic-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
  border-bottom: 1px solid var(--neutral-200);
  font-size: 1rem;
  font-weight: 500;
  color: var(--neutral-700);
  transition: color var(--transition-fast), padding-left var(--transition-fast);
}

.topic-item:hover {
  color: var(--accent-gold);
  padding-left: 8px;
}

.topic-item svg {
  width: 18px;
  height: 18px;
